WITH filtered AS (SELECT id, session_id, event_type, page, event_time, duration_sec, SUBSTRING(event_type, 1, 3) AS event_type_prefix, CONCAT_WS(',', event_type, page) AS event_type_page_key, COALESCE(page, 'NONE') AS resolved_page FROM web_events WHERE event_time >= TO_DATE('2023-04-03')), flagged AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS new_group_flag FROM filtered), sessions_web_events AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END AS new_group_flag_tier, AVG(duration_sec) FILTER (WHERE event_type = 'click') AS click_avg_duration_sec, APPROX_PERCENTILE(session_no, 0.9) AS session_no_p90, SUM(CASE WHEN page = '/search' THEN duration_sec ELSE 0 END) AS search_duration_sec FROM sessions_web_events GROUP BY ROLLUP (CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY search_duration_sec NULLS LAST;
